function(x=unit(.5,'npc'),y=unit(.5,'npc'),r=unit(.5,'snpc'),default.units='npc',name=NULL,gp=gpar(),vp=NULL) { if (!is.unit(x)) x<-unit(x,default.units); if (!is.unit(y)) y<-unit(y,default.units); if (!is.unit(r)) r<-unit(r,default.units); structure(list(primitive='circle',data=list(x=x,y=y,r=r,default.units=default.units),name=name,gp=gp,vp=vp),class=c('circle','grob','gDesc')) }
